isGRing_pairsOfPrimes_forward.signature:
theorem isGRing_pairsOfPrimes_forward.{u} (R : Type u) [CommRing R] [IsNoetherianRing R] (hR : IsGRing R)
  (q p : Ideal R) [q.IsPrime] [p.IsPrime] (hqp : q ≤ p) :
  let pbar := Ideal.map (Ideal.Quotient.mk q) p;
  let L := Localization.AtPrime pbar;
  let C := AdicCompletion (IsLocalRing.maximalIdeal L) L;
  let F := TensorProduct (R ⧸ q) q.ResidueField C;
  IsNoetherianRing F ∧ Algebra.IsGeometricallyRegular q.ResidueField F

isGRing_pairsOfPrimes_backward.signature:
theorem isGRing_pairsOfPrimes_backward.{u} (R : Type u) [CommRing R] [IsNoetherianRing R]
  (h :
    ∀ (q p : Ideal R) [inst : q.IsPrime] [inst_1 : p.IsPrime] (hqp : q ≤ p),
      let pbar := Ideal.map (Ideal.Quotient.mk q) p;
      let L := Localization.AtPrime pbar;
      let C := AdicCompletion (IsLocalRing.maximalIdeal L) L;
      let F := TensorProduct (R ⧸ q) q.ResidueField C;
      IsNoetherianRing F ∧ Algebra.IsGeometricallyRegular q.ResidueField F) :
  IsGRing R

