theorem genericFormalFiber_geometricallyRegular_of_fractionField_transport.{u} (A : Type u) [CommRing A]
  [IsDomain A] [IsNoetherianRing A] (K : Type u) [Field K] [Algebra A K] [IsFractionRing A K]
  (P : Ideal A) [P.IsPrime]
  (h :
    let C :=
      AdicCompletion (IsLocalRing.maximalIdeal (Localization.AtPrime P)) (Localization.AtPrime P);
    Algebra.IsGeometricallyRegular ⊥.ResidueField (⊥.Fiber C)) :
  let C :=
    AdicCompletion (IsLocalRing.maximalIdeal (Localization.AtPrime P)) (Localization.AtPrime P);
  Algebra.IsGeometricallyRegular K (TensorProduct A K C)

