TensorProduct.directedColimitBaseChangeE.signature:
theorem TensorProduct.directedColimitBaseChangeElementwise.{v, w} {I : Type v} [Preorder I]
  [IsDirected I fun x1 x2 => x1 ≤ x2] (F : CategoryTheory.Functor I CommRingCat)
  [CategoryTheory.Limits.HasColimit F] (i₀ : I) (M₀ : Type w) [AddCommGroup M₀]
  [Module (↑(F.obj i₀)) M₀] :
  let S := F.obj i₀;
  let R := CategoryTheory.Limits.colimit F;
  (∀ (x : TensorProduct (↑S) (↑R) M₀),
      ∃ i,
        ∃ (h : i₀ ≤ i),
          have αᵢ :=
            let __src := CommRingCat.Hom.hom (CategoryTheory.Limits.colimit.ι F i);
            { toRingHom := __src, commutes' := ⋯ };
          ∃ t, (LinearMap.rTensor M₀ αᵢ.toLinearMap) t = x) ∧
    ∀ (i : I) (h : i₀ ≤ i),
      have αᵢ :=
        let __src := CommRingCat.Hom.hom (CategoryTheory.Limits.colimit.ι F i);
        { toRingHom := __src, commutes' := ⋯ };
      ∀ (t : TensorProduct (↑S) (↑(F.obj i)) M₀),
        (LinearMap.rTensor M₀ αᵢ.toLinearMap) t = 0 →
          ∃ i',
            ∃ (h' : i ≤ i'),
              have αᵢ'ᵢ :=
                let __src := CommRingCat.Hom.hom (F.map (CategoryTheory.homOfLE h'));
                { toRingHom := __src, commutes' := ⋯ };
