theorem Polynomial.adjoinRoot_crt_matrix.{u} {A : Type u} [CommRing A] (I : Ideal A) [Nontrivial (A ⧸ I)]
  (f : Polynomial A) (hf : f.Monic) (g h : Polynomial (A ⧸ I)) (hg : g.Monic) (hh : h.Monic)
  (hcoprime : IsCoprime g h) (hfactor : Polynomial.map (Ideal.Quotient.mk I) f = g * h)
  (e : AdjoinRoot f) (he₁ : (AdjoinRoot.map (Ideal.Quotient.mk I) f g ⋯) e = 1)
  (he₀ : (AdjoinRoot.map (Ideal.Quotient.mk I) f h ⋯) e = 0) :
  have b := (AdjoinRoot.powerBasis' hf).basis;
  have T := (Algebra.leftMulMatrix b) (AdjoinRoot.root f);
  have P := (Algebra.leftMulMatrix b) e;
  have Tg := (Algebra.leftMulMatrix (AdjoinRoot.powerBasis' hg).basis) (AdjoinRoot.root g);
  have Th := (Algebra.leftMulMatrix (AdjoinRoot.powerBasis' hh).basis) (AdjoinRoot.root h);
  ∃ d U,
    ↑U * (Matrix.reindex d d) (T.map ⇑(Ideal.Quotient.mk I)) * ↑U⁻¹ = Matrix.fromBlocks Tg 0 0 Th ∧
      ↑U * (Matrix.reindex d d) (P.map ⇑(Ideal.Quotient.mk I)) * ↑U⁻¹ = Matrix.fromBlocks 1 0 0 0

