MvPolynomial.linearEquationLocalizationP.signature:
theorem MvPolynomial.linearEquationLocalizationPolynomialFormula.{u} (A : Type u) [CommRing A] (r : ℕ)
  (f : Fin r → A) (i : Fin r) :
  have I := Ideal.span {∑ j, MvPolynomial.C (f j) * MvPolynomial.X j - 1};
  let B := MvPolynomial (Fin r) A ⧸ I;
  have q := Ideal.Quotient.mk I;
  let Af := Localization.Away (f i);
  let Bf := Localization.Away ((Algebra.algebraMap A B) (f i));
  have this := (Localization.awayMap (Algebra.algebraMap A B) (f i)).toAlgebra;
  have x := fun j => (Algebra.algebraMap B Bf) (q (MvPolynomial.X j));
  ∀ (e : MvPolynomial { j // j ≠ i } Af ≃ₐ[Af] Bf),
    (↑e = MvPolynomial.aeval fun j => x ↑j) →
      (∀ (j : { j // j ≠ i }), e.symm (x ↑j) = MvPolynomial.X j) →
        e.symm (x i) =
          MvPolynomial.C (IsLocalization.Away.invSelf (f i)) *
            (1 - ∑ j, MvPolynomial.C ((Algebra.algebraMap A Af) (f ↑j)) * MvPolynomial.X j)

theorem MvPolynomial.linearEquationLocalizationPolynomialCore.{u} (A : Type u) [CommRing A] (r : ℕ)
  (f : Fin r → A) (i : Fin r) :
  have I := Ideal.span {∑ j, MvPolynomial.C (f j) * MvPolynomial.X j - 1};
  let B := MvPolynomial (Fin r) A ⧸ I;
  have q := Ideal.Quotient.mk I;
  let Af := Localization.Away (f i);
  let Bf := Localization.Away ((Algebra.algebraMap A B) (f i));
  have x := fun j => (Algebra.algebraMap B Bf) (q (MvPolynomial.X j));
  ∃ e,
    (↑e = MvPolynomial.aeval fun j => x ↑j) ∧
      ∀ (j : { j // j ≠ i }), e.symm (x ↑j) = MvPolynomial.X j

