AlgebraicGeometry.etale_restriction_pull.signature:
theorem AlgebraicGeometry.etale_restriction_pullback_unit_eq.{u} {X Y W W' : AlgebraicGeometry.Scheme}
  (g : Y ⟶ X) (p : W ⟶ X) (g' : W' ⟶ W) (p' : W' ⟶ Y)
  (hcomm : CategoryTheory.CategoryStruct.comp g' p = CategoryTheory.CategoryStruct.comp p' g)
  (ι : W' ⟶ CategoryTheory.Limits.pullback p g)
  (hι₁ : CategoryTheory.CategoryStruct.comp ι (CategoryTheory.Limits.pullback.fst p g) = g')
  (hι₂ : CategoryTheory.CategoryStruct.comp ι (CategoryTheory.Limits.pullback.snd p g) = p')
  [CategoryTheory.IsIso ι] [hp : AlgebraicGeometry.Etale p] (hp' : AlgebraicGeometry.Etale p') :
  let A := AddCommGrpCat;
  let w := AlgebraicGeometry.Scheme.Etale.mk (CategoryTheory.CategoryStruct.id W);
  let w' := AlgebraicGeometry.Scheme.Etale.mk (CategoryTheory.CategoryStruct.id W');
  let wx := AlgebraicGeometry.Scheme.Etale.mk p;
  let wy' := AlgebraicGeometry.Scheme.Etale.mk p';
  have eW := CategoryTheory.MorphismProperty.Over.isoMk (CategoryTheory.Iso.refl W) ⋯;
  have eW' := CategoryTheory.MorphismProperty.Over.isoMk (CategoryTheory.Iso.refl W') ⋯;
  have theta :=
    CategoryTheory.MorphismProperty.Over.homMk
      (CategoryTheory.Limits.pullback.lift g' (CategoryTheory.CategoryStruct.id W') ⋯) ⋯ ⋯;
  have iotaSite := CategoryTheory.MorphismProperty.Over.homMk ι hι₂ ⋯;
  ∀ (F : CategoryTheory.Sheaf X.smallEtaleTopology A),
    let pF := (AlgebraicGeometry.Etale.upperStar A p).obj F;
    let gF := (AlgebraicGeometry.Etale.upperStar A g).obj F;
    let K := (AlgebraicGeometry.Etale.upperStar A g').obj pF;
    have rhoF := (AlgebraicGeometry.Etale.upperStarIsoLocalizationRestriction A p hp).hom.app F;
    have rhoG := (AlgebraicGeometry.Etale.upperStarIsoLocalizationRestriction A p' hp').hom.app gF;
    have kappa :=
      CategoryTheory.CategoryStruct.comp
        ((AlgebraicGeometry.Etale.upperStarComp A g' p (CategoryTheory.CategoryStruct.comp g' p)
                ⋯).inv.app
          F)
        ((AlgebraicGeometry.Etale.upperStarComp A p' g (CategoryTheory.CategoryStruct.comp g' p)
                hcomm).hom.app
          F);
    CategoryTheory.CategoryStruct.comp
        (((AlgebraicGeometry.Etale.upperStarLowerStarAdjunction A g').unit.app pF).hom.app
          (Opposite.op w))
        (CategoryTheory.CategoryStruct.comp (K.obj.map theta.op)
          (CategoryTheory.CategoryStruct.comp (kappa.hom.app (Opposite.op w'))
            (CategoryTheory.CategoryStruct.comp (rhoG.hom.app (Opposite.op w'))
              (gF.obj.map eW'.inv.op)))) =
      CategoryTheory.CategoryStruct.comp (rhoF.hom.app (Opposite.op w))
        (CategoryTheory.CategoryStruct.comp (F.obj.map eW.inv.op)
          (CategoryTheory.CategoryStruct.comp
            (((AlgebraicGeometry.Etale.upperStarLowerStarAdjunction A g).unit.app F).hom.app
              (Opposite.op wx))
            (gF.obj.map iotaSite.op)))

