AlgebraicGeometry.Scheme.finiteEtale_gra.signature:
theorem AlgebraicGeometry.Scheme.finiteEtale_graph_base_change.{u} {Y Y₀ U V : AlgebraicGeometry.Scheme}
  (p : U ⟶ Y) (q : V ⟶ Y) [AlgebraicGeometry.IsFinite q] [AlgebraicGeometry.Etale q] (i : Y₀ ⟶ Y) :
  let p₀ := CategoryTheory.Limits.pullback.snd p i;
  let q₀ := CategoryTheory.Limits.pullback.snd q i;
  have j :=
    CategoryTheory.Limits.pullback.map q₀ p₀ q p (CategoryTheory.Limits.pullback.fst q i)
      (CategoryTheory.Limits.pullback.fst p i) i ⋯ ⋯;
  CategoryTheory.IsPullback j (CategoryTheory.Limits.pullback.snd q₀ p₀)
      (CategoryTheory.Limits.pullback.snd q p) (CategoryTheory.Limits.pullback.fst p i) ∧
    ∀ (a : U ⟶ V) (ha : CategoryTheory.CategoryStruct.comp a q = p),
      let a₀ :=
        CategoryTheory.Limits.pullback.lift
          (CategoryTheory.CategoryStruct.comp (CategoryTheory.Limits.pullback.fst p i) a) p₀ ⋯;
      Set.range
          ⇑(CategoryTheory.Limits.pullback.lift a₀
              (CategoryTheory.CategoryStruct.id (CategoryTheory.Limits.pullback p i)) ⋯) =
        ⇑j ⁻¹'
          Set.range ⇑(CategoryTheory.Limits.pullback.lift a (CategoryTheory.CategoryStruct.id U) ⋯)

