AlgebraicGeometry.IsCurve.finite_pushfor.signature:
theorem AlgebraicGeometry.IsCurve.finite_pushforward_cohomology_comparison.{u} {k : Type u} [Field k]
  [IsAlgClosed k] (P : AlgebraicGeometry.CurveCoefficientPair k) {Y : AlgebraicGeometry.Scheme}
  (g : Y ⟶ AlgebraicGeometry.Spec (CommRingCat.of k)) [AlgebraicGeometry.IsCurve g] (f : P.C ⟶ Y)
  [AlgebraicGeometry.IsFinite f] (_hf : CategoryTheory.CategoryStruct.comp f g = P.toSpec) :
  let E :=
    (CategoryTheory.forget₂ (ModuleCat ℤ) AddCommGrpCat).inv.comp
      (ModuleCat.restrictScalars ULift.ringEquiv.toRingHom);
  have FX := (CategoryTheory.sheafCompose P.C.smallEtaleTopology E).obj P.F;
  have G := (AlgebraicGeometry.Etale.lowerStar AddCommGrpCat f).obj P.F;
  have FY := (CategoryTheory.sheafCompose Y.smallEtaleTopology E).obj G;
  ∀ (q : ℕ),
    Nonempty
      (((CategoryTheory.sheafCompose Y.smallEtaleTopology
                  (CategoryTheory.forget₂ (ModuleCat (ULift.{u + 1, 0} ℤ)) AddCommGrpCat)).obj
              FY).H
          q ≃+
        ((CategoryTheory.sheafCompose P.C.smallEtaleTopology
                  (CategoryTheory.forget₂ (ModuleCat (ULift.{u + 1, 0} ℤ)) AddCommGrpCat)).obj
              FX).H
          q)

