Algebra.singularIdeal.doc:
The singular ideal `H_{A/R}` is the radical of the ideal generated by elements `g`
for which `A_g` is smooth over `R`. Source: Stacks Project, Smoothing Ring Maps,
Definition 07C5 (blueprint: def-weil-pbc-singular-ideal).

Algebra.jacobiZariski_leftTerm_vanishing.signature:
theorem Algebra.jacobiZariski_leftTerm_vanishing.{u, v} (A : Type u) (B : Type v) [CommRing A] [CommRing B]
  [Algebra A B] [Subsingleton (Algebra.H1Cotangent A B)] [Module.Projective B Ω[B⁄A]]
  (a : Ideal B) :
  have P := (Algebra.Generators.self A B).toExtension;
  have δ := LinearMap.rTensor (B ⧸ a) P.cotangentComplex;
  have ι := LinearMap.rTensor (B ⧸ a) Algebra.Extension.h1Cotangentι;
  Function.Injective ⇑ι ∧
    ι.range = δ.ker ∧
      Nonempty (↥δ.ker ≃ₗ[B] TensorProduct B (Algebra.H1Cotangent A B) (B ⧸ a)) ∧
        Subsingleton (TensorProduct B (Algebra.H1Cotangent A B) (B ⧸ a)) ∧ Subsingleton ↥δ.ker

Algebra.ind_smooth_quotient_compatibilit.signature:
theorem Algebra.ind_smooth_quotient_compatibility.{u, v} (R : Type u) [CommRing R] (Λ : Type (max u v))
  [CommRing Λ] [Algebra R Λ] (I K : Ideal R) (hKI : K ≤ I)
  (hΛ :
    CategoryTheory.ObjectProperty.ind (fun C => Algebra.Smooth (R ⧸ I) ↑C)
      (CommAlgCat.of (R ⧸ I) (Λ ⧸ Ideal.map (Algebra.algebraMap R Λ) I))) :
  let R' := R ⧸ K;
  let Λ' := Λ ⧸ Ideal.map (Algebra.algebraMap R Λ) K;
  have I' := Ideal.map (Ideal.Quotient.mk K) I;
  CategoryTheory.ObjectProperty.ind (fun C => Algebra.Smooth (R' ⧸ I') ↑C)
    (CommAlgCat.of (R' ⧸ I') (Λ' ⧸ Ideal.map (Algebra.algebraMap R' Λ') I'))

