AdicCompletion.exists_local_completion_q.signature:
theorem AdicCompletion.exists_local_completion_quotient.{u, v} (A : Type u) (B : Type v) [CommRing A]
  [CommRing B] [IsNoetherianRing A] [IsLocalRing A] (φ : A →+* B) (hφ : Function.Surjective ⇑φ) :
  have m := IsLocalRing.maximalIdeal A;
  have n := Ideal.map φ m;
  let Ahat := AdicCompletion m A;
  let Bhat := AdicCompletion n B;
  have cA := Algebra.algebraMap A Ahat;
  have cB := Algebra.algebraMap B Bhat;
  have Jhat := Ideal.map cA (RingHom.ker φ);
  (∀ (k : ℕ), Ideal.map φ (m ^ k) = n ^ k) ∧
    ∃ θ,
      (∀ (k : ℕ),
          ∃ θk,
            Function.Surjective ⇑θk ∧
              θk.comp (Ideal.Quotient.mk (m ^ k)) = (Ideal.Quotient.mk (n ^ k)).comp φ ∧
                (AdicCompletion.evalₐ n k).comp θ = θk.comp (AdicCompletion.evalₐ m k).toRingHom) ∧
        θ.comp cA = cB.comp φ ∧
          Function.Surjective ⇑θ ∧
            RingHom.ker θ = Jhat ∧ ∃ e, ∀ (x : Ahat), e ((Ideal.Quotient.mk Jhat) x) = θ x

